import { createClient } from "@supabase/supabase-js";

const supabaseUrl = process.env.REACT_APP_SUPABASE_URL;
// Publishable keys are intended for browser use. Keep the legacy variable as a compatibility fallback.
const supabaseAnonKey = process.env.REACT_APP_SUPABASE_PUBLISHABLE_KEY || process.env.REACT_APP_SUPABASE_ANON_KEY;

export const isSupabaseConfigured = Boolean(supabaseUrl && supabaseAnonKey);
export const supabase = isSupabaseConfigured
  ? createClient(supabaseUrl, supabaseAnonKey)
  : null;

export async function getProducts() {
  if (!supabase) return null;
  const { data, error } = await supabase
    .from("products")
    .select("id,title,description,category,price,image")
    .eq("is_active", true)
    .order("id");
  if (error) throw error;
  return data.map((product) => ({
    ...product,
    desc: product.description,
    img: product.image,
    amount: 1,
    price: String(product.price),
  }));
}

export async function createReview({ name, rating, message }) {
  if (!supabase) throw new Error("Supabase ще не налаштовано.");
  const { error } = await supabase.from("reviews").insert({
    customer_name: name.trim() || "Гість",
    rating,
    message: message.trim(),
  });
  if (error) throw error;
}

export async function createOrder({ name, phone, address, notes, items }) {
  if (!supabase) throw new Error("Supabase ще не налаштовано.");
  const payload = items.map((item) => ({
    product_id: Number(item.id),
    quantity: Number(item.amount),
  }));
  const { data, error } = await supabase.rpc("submit_order", {
    p_name: name,
    p_phone: phone,
    p_address: address,
    p_notes: notes || "",
    p_items: payload,
  });
  if (error) throw error;
  return data;
}


export async function getAdminOrders() {
  if (!supabase) throw new Error("Supabase ще не налаштовано.");
  const { data, error } = await supabase
    .from("orders")
    .select("id,created_at,status,total,delivery_address,notes,customer:customers(name,phone),items:order_items(id,product_title,unit_price,quantity,line_total)")
    .order("created_at", { ascending: false })
    .limit(100);
  if (error) throw error;
  return data || [];
}

export async function updateAdminOrderStatus(orderId, status) {
  if (!supabase) throw new Error("Supabase ще не налаштовано.");
  const allowed = ["new", "confirmed", "preparing", "delivering", "completed", "cancelled"];
  if (!allowed.includes(status)) throw new Error("Невідомий статус замовлення.");
  const { error } = await supabase.from("orders").update({ status }).eq("id", orderId);
  if (error) throw error;
}


export async function getBuyerOrderHistory() {
  if (!supabase) throw new Error("Supabase ще не налаштовано.");
  const { data, error } = await supabase
    .from("orders")
    .select("id,created_at,status,total,delivery_address,notes,customer_name,customer_phone,items:order_items(id,product_title,unit_price,quantity,line_total)")
    .order("created_at", { ascending: false });
  if (error) throw error;
  return data || [];
}

export async function deleteAdminOrder(orderId) {
  if (!supabase) throw new Error("Supabase ще не налаштовано.");
  const { error } = await supabase.from("orders").delete().eq("id", orderId);
  if (error) throw error;
}
